import { useEffect, useRef, useState } from 'react';
import type { FormEvent, ReactNode } from 'react';
import * as Dialog from '@radix-ui/react-dialog';
import { ArrowDownToLine, ArrowRight, ArrowUpRight, BadgeCheck, Banknote, BookOpen, CheckCheck, ChevronDown, ChevronRight, CircleAlert, CircleCheck, Clock3, FileCheck2, FileText, FolderOpen, HelpCircle, History, IndianRupee, Layers3, LayoutDashboard, LoaderCircle, Menu, Plus, RefreshCw, Search, ShieldCheck, Sparkles, UploadCloud, X } from 'lucide-react';

type Item = Record<string, any>;
type View = 'overview' | 'documents' | 'ledger' | 'interest' | 'review' | 'audit';
const nav: { id: View; label: string; icon: typeof LayoutDashboard }[] = [
  { id: 'overview', label: 'Claim workspace', icon: LayoutDashboard }, { id: 'documents', label: 'Evidence library', icon: FolderOpen },
  { id: 'ledger', label: 'Invoices & payments', icon: Banknote }, { id: 'interest', label: 'Interest schedule', icon: IndianRupee },
  { id: 'review', label: 'Review & export', icon: FileCheck2 }, { id: 'audit', label: 'Activity log', icon: History },
];
const rupees = (value: unknown) => new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 2 }).format(Number(value || 0));
const date = (value: unknown) => value ? new Date(String(value)).toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' }) : 'Awaiting evidence';
const list = (value: any): Item[] => Array.isArray(value) ? value : [];
const statusLabel: Record<string, string> = { draft: 'Needs documents', review_required: 'Review required', ready: 'Ready for approval', approved: 'Approved' };
const needsReview = (status: string) => ['failed', 'unreadable', 'unsupported', 'needs_review', 'ocr_unavailable', 'parse_error', 'unstructured_review', 'extracted_needs_review'].includes(status);
const sourceStatus = (status: string) => ({parsed:'Parsed',reviewed:'Reviewed',superseded:'Replaced',ocr_unavailable:'Unreadable scan',parse_error:'Parse failed',unstructured_review:'Needs extraction review',extracted_needs_review:'Proposed facts · review required'}[status] || String(status || 'Uploaded').replaceAll('_',' '));

async function api(path: string, options?: RequestInit) {
  const response = await fetch(`/api${path}`, options);
  if (!response.ok) {
    let error;
    try { error = await response.json(); } catch { error = null; }
    const detail = error?.detail;
    throw new Error(typeof detail === 'string' ? detail : Array.isArray(detail) ? detail.map((x: Item) => x.msg).join('; ') : detail?.message || error?.message || `Request could not be completed (${response.status}).`);
  }
  return response.json();
}
const json = (body: Item, method = 'POST'): RequestInit => ({ method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });

function Badge({ children, tone = 'neutral' }: { children: ReactNode; tone?: string }) { return <span className={`badge badge-${tone}`}>{children}</span>; }
function Empty({ title, children, icon: Icon = FolderOpen }: { title: string; children: ReactNode; icon?: typeof FolderOpen }) { return <div className="empty"><span className="empty-icon"><Icon size={24} /></span><h3>{title}</h3><p>{children}</p></div>; }

export default function App() {
  const [view, setView] = useState<View>('overview');
  const [claim, setClaim] = useState<Item | null>(null);
  const [cases, setCases] = useState<Item[]>([]);
  const [busy, setBusy] = useState('');
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [modal, setModal] = useState(false);
  const [source, setSource] = useState<Item | null>(null);
  const [menu, setMenu] = useState(false);
  const [query, setQuery] = useState('');
  const [help, setHelp] = useState(false);
  const [selectedInvoiceId, setSelectedInvoiceId] = useState('');
  const [invoiceFilter, setInvoiceFilter] = useState('all');
  const [modelPlanning, setModelPlanning] = useState(false);
  const [reviewer, setReviewer] = useState('');
  const [buyerConfirmed, setBuyerConfirmed] = useState(false);
  const [rateConfirmed, setRateConfirmed] = useState(false);
  const [approvalChecked, setApprovalChecked] = useState(false);
  const [resolutions, setResolutions] = useState<Record<string, { invoice: string; reason: string; source: string }>>({});
  const [sourceReviews, setSourceReviews] = useState<Record<string, { reason: string; replacement: string }>>({});
  const [invoiceEdits, setInvoiceEdits] = useState<Record<string, Item>>({});
  const fileRef = useRef<HTMLInputElement>(null);
  const sources = list(claim?.sources);
  const invoices = list(claim?.invoices);
  const payments = list(claim?.payments);
  const blockers = list(claim?.blockers);
  const totals = claim?.totals || {};
  const evaluated = claim?.evaluation?.metrics || claim?.evaluation;
  const synthetic = claim?.synthetic || claim?.is_demo || list(claim?.rates).some(r => r.synthetic) || sources.some(s => String(s.file).includes('synthetic')) || String(claim?.name || '').toLowerCase().includes('demo');

  useEffect(() => {
    setBusy('Loading workspace');
    api('/cases').then(async result => {
      const rows = list(result?.cases ?? result); setCases(rows);
      const saved = localStorage.getItem('bakaya.case');
      const active = rows.find(c => c.id === saved) || rows[0];
      if (active) setClaim(await api(`/cases/${active.id}`));
    }).catch(e => setError(e.message)).finally(() => setBusy(''));
  }, []);

  useEffect(() => {
    setBuyerConfirmed(Boolean(claim?.review?.buyer_confirmed));
    setRateConfirmed(Boolean(claim?.review?.rate_confirmed));
    setReviewer(claim?.review?.reviewer || claim?.approval?.reviewer || '');
    setApprovalChecked(false);
    setSourceReviews({});
  }, [claim?.id, claim?.revision]);

  useEffect(() => { setSource(null); setSelectedInvoiceId(''); }, [claim?.id]);

  async function perform(label: string, action: () => Promise<any>, message?: string) {
    setBusy(label); setError(''); setNotice('');
    try {
      const result = await action();
      if (result?.id) { setClaim(result); localStorage.setItem('bakaya.case', result.id); }
      if (message) setNotice(message);
      return result;
    } catch (e) { setError(e instanceof Error ? e.message : 'Something went wrong. Please try again.'); }
    finally { setBusy(''); }
  }

  async function loadDemo() {
    const result = await perform('Preparing synthetic case', () => api('/cases/demo', json({})), 'Synthetic records loaded. Review the open questions before approving.');
    if (result) { setCases(prev => [result, ...prev.filter(c => c.id !== result.id)]); setView('overview'); setBuyerConfirmed(false); setRateConfirmed(false); setApprovalChecked(false); setResolutions({}); }
  }
  async function selectCase(id: string) {
    await perform('Opening case', () => api(`/cases/${id}`));
    setResolutions({}); setBuyerConfirmed(false); setRateConfirmed(false); setApprovalChecked(false); setView('overview');
  }
  async function uploadFiles(files: FileList | null) {
    if (!files?.length || !claim) return;
    const form = new FormData(); Array.from(files).forEach(f => form.append('files', f));
    await perform('Reading documents', async () => {
      await api(`/cases/${claim.id}/upload`, { method: 'POST', body: form });
      return api(`/cases/${claim.id}/run`, json({ mode: 'fixed' }));
    }, 'Documents added and claim recalculated.');
    setApprovalChecked(false);
    if (fileRef.current) fileRef.current.value = '';
  }
  function openSource(ref: any, context?: Item) {
    if (view !== 'review') setView('documents');
    const id = typeof ref === 'string' ? ref : ref?.source_id || ref?.id;
    const found = sources.find(s => s.id === id || s.file === ref?.file);
    setSource({ ...found, ...typeof ref === 'object' ? ref : {}, file: found?.file || ref?.file || id || 'Source reference', text: ref?.text || ref?.excerpt || found?.text || 'This reference has no extracted text.', related_refs: context?.related_refs || context?.source_refs || [], field_sources: context?.field_sources || {}, record_context: context?.record_context || context });
  }
  function refs(item: Item) {
    let items = list(item.source_refs);
    if (!items.length && item.source_ref) items = [item.source_ref];
    if (!items.length && item.source_id) items = [{ source_id: item.source_id }];
    return items.length ? <button className="source-link" onClick={() => openSource(items[0], item)}><FileText size={12} /> View source{items.length > 1 ? ` (${items.length})` : ''} <ArrowUpRight size={11} /></button> : <span className="muted small">No source attached</span>;
  }

  async function saveReview() {
    if (!claim) return;
    const choices = Object.entries(resolutions).filter(([, r]) => r.invoice);
    await perform('Saving review decisions', () => api(`/cases/${claim.id}/review`, json({
      reviewer: reviewer.trim(), buyer_confirmed: buyerConfirmed, rate_confirmed: rateConfirmed,
      resolutions: choices.map(([paymentId, r]) => ({ payment_id: paymentId, allocations: [{ invoice_id: r.invoice, amount: String(payments.find(p => p.id === paymentId)?.amount || '0'), tds_amount: '0' }], reason: r.reason, source_id: r.source || undefined })),
      source_reviews: Object.entries(sourceReviews).filter(([, r]) => r.reason.trim().length >= 5).map(([sourceId, r]) => ({ source_id: sourceId, reason: r.reason, replacement_source_id: r.replacement })),
      invoice_updates: Object.entries(invoiceEdits).filter(([,r]) => Object.keys(r.fields || {}).length > 0).map(([invoiceId,r]) => ({invoice_id:invoiceId,source_id:r.source_id,reason:r.reason,fields:r.fields})),
    })), 'Review decisions saved. Verification has been rerun.');
    setResolutions({}); setSourceReviews({}); setInvoiceEdits({}); setApprovalChecked(false);
  }
  async function approve() {
    if (!claim) return;
    await perform('Recording your approval', () => api(`/cases/${claim.id}/approve`, json({ reviewer: reviewer.trim() })), 'Approval recorded. Your packet is ready to download.');
  }
  async function download() {
    if (!claim) return;
    await perform('Building claim packet', async () => {
      const response = await fetch(`/api/cases/${claim.id}/export`);
      if (!response.ok) { const result = await response.json().catch(() => null); throw new Error(result?.detail || 'Packet export failed.'); }
      const blob = await response.blob(); const url = URL.createObjectURL(blob);
      const a = document.createElement('a'); a.href = url; a.download = `Bakaya-${claim.id}-claim-packet.zip`; a.click(); URL.revokeObjectURL(url);
      return api(`/cases/${claim.id}`);
    }, 'Claim packet downloaded.');
  }

  const filteredInvoices = invoices.filter(i => `${i.number} ${i.id}`.toLowerCase().includes(query.toLowerCase()));
  const currentLabel = nav.find(n => n.id === view)?.label;

  const selectedInvoice = invoices.find(i => i.id === selectedInvoiceId) || invoices[0];
  const activeSource = (source?.id ? {...source,...sources.find(s => s.id === source.id)} : source) || (view === 'review' ? sources.find(s => s.kind === 'remittance_note') : undefined) || sources[0];
  const activeRecord = [...invoices,...payments].find(r => r.id === source?.record_context?.id) || [...invoices, ...payments].find(i => list(i.source_refs).includes(activeSource?.id));
  const auditRows = [...list(claim?.audit)].reverse();
  const preparationAgent = claim?.agent;
  const eligibleRows = filteredInvoices.filter(i => invoiceFilter === 'all' || (invoiceFilter === 'outstanding' ? Number(i.outstanding) > 0 : Number(i.outstanding) === 0));
  const canSaveReview = !!claim && !busy && !!reviewer.trim() && !Object.values(resolutions).some(r => r.invoice && (r.reason.trim().length < 5 || !r.source)) && !Object.values(invoiceEdits).some(r => Object.keys(r.fields || {}).length > 0 && (!r.source_id || String(r.reason || '').trim().length < 5));

  function goTo(next: View) { setView(next); setMenu(false); setSource(null); }
  async function runPreparation(resume = false, failure = false) {
    if (!claim) return;
    await perform(resume ? 'Resuming preparation' : 'Preparing claim', () => api(`/cases/${claim.id}/agent/${resume ? 'resume' : 'run'}`, json({ max_steps: 8, allow_model_planning: modelPlanning, allow_model_extraction: false, simulate_tool_failure: failure })), 'Preparation state updated. Review the recorded steps and open questions.');
  }

  function invoiceLedger() {
    return <section className="panel ledger-panel">
      <div className="panel-heading"><div><h2>Invoice ledger <span className="count-pill">{invoices.length}</span></h2><p>Review amounts and evidence before confirming this claim.</p></div><div className="ledger-tools"><label className="search-box"><Search size={16}/><input aria-label="Find an invoice" placeholder="Search invoices…" value={query} onChange={e => setQuery(e.target.value)}/></label><select aria-label="Filter invoices" value={invoiceFilter} onChange={e => setInvoiceFilter(e.target.value)}><option value="all">All invoices</option><option value="outstanding">Principal outstanding</option><option value="settled">Principal settled</option></select></div></div>
      {eligibleRows.length ? <div className="table-wrap"><table className="ledger-table"><thead><tr><th>Invoice</th><th>Due date</th><th className="numeric">Invoiced</th><th className="numeric">Outstanding</th><th className="numeric">Interest</th><th>Evidence</th></tr></thead><tbody>{eligibleRows.map(i => <tr key={i.id} className={selectedInvoice?.id === i.id ? 'selected-row' : ''}><td><button className="invoice-select" onClick={() => setSelectedInvoiceId(i.id)} aria-pressed={selectedInvoice?.id === i.id}>{i.number || i.id}<ChevronRight size={12}/></button><span className="table-sub">Issued {date(i.date || i.invoice_date)}</span></td><td>{date(i.due_date)}<span className="table-sub">{Number(i.outstanding) === 0 ? 'Principal settled' : 'Section 15 deadline'}</span></td><td className="numeric money">{rupees(i.amount)}</td><td className="numeric money">{rupees(i.outstanding)}</td><td className="numeric money">{rupees(i.interest)}</td><td>{refs(i)}</td></tr>)}</tbody></table></div> : <Empty title={query || invoiceFilter !== 'all' ? 'No invoices match this view' : 'Add the invoices for this buyer'} icon={FileText}>{query || invoiceFilter !== 'all' ? 'Change the search or filter to see other records.' : 'Upload supported records with invoice amounts and acceptance evidence.'}</Empty>}
      <div className="ledger-totals"><div><span>Outstanding principal</span><strong>{rupees(totals.principal)}</strong><small>After allocated receipts and evidenced TDS</small></div><div><span>Calculated interest</span><strong>{rupees(totals.interest)}</strong><small>Through {date(claim?.as_of)}</small></div><div className="ledger-total-claim"><span>Total claim</span><strong>{rupees(totals.total)}</strong><small>Principal + calculated interest</small></div></div>
      {Number(totals.unallocated) > 0 && <div className="ledger-warning"><CircleAlert size={16}/>{rupees(totals.unallocated)} in bank receipts still needs allocation. The figures above remain provisional.</div>}
    </section>;
  }

  function activityTable(compact = false) {
    const rows = compact ? auditRows.slice(0, 4) : auditRows;
    return <section className="panel activity-panel"><div className="panel-heading"><div><h2>{compact ? 'Recent decisions' : 'Activity log'}</h2><p>Recorded actions and the reasons behind them.</p></div>{compact && <button className="text-button" onClick={() => goTo('audit')}>View full log <ArrowRight size={14}/></button>}</div>{rows.length ? <div className="table-wrap"><table className="activity-table"><thead><tr><th>Time</th><th>Action</th><th>Recorded detail</th></tr></thead><tbody>{rows.map((a, idx) => <tr key={idx}><td>{a.at ? new Date(a.at).toLocaleTimeString('en-IN', {hour:'2-digit',minute:'2-digit'}) : 'Not recorded'}<span className="table-sub">{date(a.at)}</span></td><td><strong>{String(a.action).replaceAll('_',' ')}</strong></td><td>{typeof a.detail === 'object' ? JSON.stringify(a.detail) : a.detail}</td></tr>)}</tbody></table></div> : <Empty title="No recorded actions yet" icon={History}>Create a claim to begin its audit trail.</Empty>}</section>;
  }

  function selectedRecordPanel() {
    const recordSources = list(selectedInvoice?.source_refs).map((ref: any) => sources.find(s => s.id === (typeof ref === 'string' ? ref : ref.source_id))).filter(Boolean);
    const recordMatches = list(claim?.matches).filter(m => m.invoice_id === selectedInvoice?.id);
    return <aside className="panel record-detail"><div className="panel-heading"><div><h2>{selectedInvoice?.number || 'Invoice detail'}</h2><p>{selectedInvoice ? 'Evidence and calculations for this invoice.' : 'Choose a record in the ledger.'}</p></div><FileText size={20}/></div>{selectedInvoice ? <div className="record-detail-body"><dl className="record-facts"><div><dt>Invoice amount</dt><dd>{rupees(selectedInvoice.amount)}</dd></div><div><dt>Principal outstanding</dt><dd>{rupees(selectedInvoice.outstanding)}</dd></div><div><dt>Calculated interest</dt><dd>{rupees(selectedInvoice.interest)}</dd></div><div><dt>Due date</dt><dd>{date(selectedInvoice.due_date)}</dd></div><div><dt>Acceptance / delivery</dt><dd>{date(selectedInvoice.acceptance_date || selectedInvoice.delivery_date)}</dd></div></dl><h3>Linked evidence</h3>{recordSources.map((s: any) => <button key={s.id} className="linked-document" onClick={() => openSource(s, selectedInvoice)}><FileText size={17}/><span><strong>{s.file}</strong><small>{sourceStatus(s.status)}{s.page ? ` · page ${s.page}` : s.line ? ` · line ${s.line}` : ''}</small></span><ArrowUpRight size={13}/></button>)}{!recordSources.length && <p className="muted">No source is linked to this record.</p>}<h3>Payment allocations</h3>{recordMatches.length ? recordMatches.map((m,idx) => <div className="allocation-detail" key={idx}><span><Banknote size={14}/>{m.payment_id}</span><strong>{rupees(m.amount)}</strong><p>{m.reason}{Number(m.tds_amount) > 0 ? ` · ${rupees(m.tds_amount)} evidenced TDS` : ''}</p>{refs(m)}</div>) : <p className="muted">No payment has been allocated to this invoice.</p>}<div className="detail-note"><ShieldCheck size={16}/><p>Due dates and interest follow the documented rules. Verify the source facts before approval.</p></div><button className="button primary full-width" onClick={() => goTo('review')}>Review claim packet <ArrowRight size={16}/></button></div> : <Empty title="Select an invoice">Its linked evidence will appear here.</Empty>}</aside>;
  }

  function evidenceWorkspace() {
    const sourceId = activeSource?.id;
    const recordFields = activeRecord ? Object.entries(activeRecord.field_sources || {}) as [string,string[]][] : [];
    const recordsForSource = [...invoices,...payments].filter(i => list(i.source_refs).includes(sourceId));
    const fileUrl = sourceId && claim ? `/api/cases/${claim.id}/sources/${sourceId}/download` : '';
    const isPdf = !!activeSource?.stored_name && /\.pdf$/i.test(activeSource.file || '');
    const isImage = !!activeSource?.stored_name && /\.(png|jpe?g|webp|tiff?)$/i.test(activeSource.file || '');
    const textLines = String(activeSource?.text || 'No extracted text is available. Open the original file or supply readable alternative evidence.').split('\n');
    return <section className="evidence-workspace" aria-label="Evidence review workspace">
      <aside className="panel evidence-browser"><div className="panel-heading"><div><h2>Documents <span className="count-pill">{sources.length}</span></h2><p>Original records in this claim.</p></div></div><div className="evidence-file-list">{sources.map(s => <button className={`evidence-file ${sourceId === s.id ? 'selected-file' : ''}`} key={s.id} onClick={() => openSource(s, [...invoices,...payments].find(r => list(r.source_refs).includes(s.id)))}><span className="file-thumbnail"><FileText size={23}/><span>{(s.file?.split('.').pop() || 'DOC').toUpperCase()}</span></span><span className="file-title"><strong>{s.file}</strong><small>{String(s.kind || 'Document').replaceAll('_',' ')}</small><Badge tone={needsReview(s.status) ? 'amber' : s.status === 'superseded' ? 'neutral' : 'green'}>{sourceStatus(s.status)}</Badge></span><ChevronRight size={13}/></button>)}</div><button className="button secondary add-evidence" disabled={!claim || !!busy} onClick={() => fileRef.current?.click()}><Plus size={15}/> Add documents</button></aside>
      <section className="panel evidence-document"><div className="panel-heading"><div><h2>{activeSource?.file || 'Source document'}</h2><p>{activeSource ? `${String(activeSource.kind || 'Evidence').replaceAll('_',' ')}${activeSource.page ? ` · page ${activeSource.page}` : ''}${activeSource.line ? ` · line ${activeSource.line}` : ''}` : 'Choose a document to inspect.'}</p></div>{activeSource && <Badge tone={needsReview(activeSource.status) ? 'amber' : activeSource.status === 'superseded' ? 'neutral' : 'green'}>{sourceStatus(activeSource.status)}</Badge>}</div><div className="document-toolbar"><span><FileText size={14}/>{isPdf || isImage ? 'Original file' : 'Extracted source text'}</span>{activeSource?.stored_name && <a className="text-button" href={fileUrl} download><ArrowDownToLine size={15}/> Download original</a>}</div><div className="document-stage">{activeSource ? isPdf ? <iframe title={`Original ${activeSource.file}`} src={fileUrl}/> : isImage ? <img className="original-image" src={fileUrl} alt={`Uploaded evidence: ${activeSource.file}`}/> : <article className="source-paper"><div className="source-paper-heading"><FileText size={25}/><div><strong>{activeSource.file}</strong><span>{synthetic ? 'Synthetic record · source text' : 'Uploaded record · extracted text'}</span></div></div><div className="document-lines">{textLines.map((line,idx) => <div className="document-line" key={idx}><span>{(activeSource.line || 1)+idx}</span><p>{line || '\u00a0'}</p></div>)}</div>{needsReview(activeSource.status) && <div className="document-status-note"><CircleAlert size={17}/><p>{sourceStatus(activeSource.status)}. This source needs review or readable replacement evidence before approval.</p></div>}</article> : <Empty title="No evidence to inspect">Create a claim and upload its records.</Empty>}</div>{activeSource?.sha256 && <details className="fingerprint"><summary><ShieldCheck size={14}/> Stored file fingerprint</summary><code>{activeSource.sha256}</code><p>Identifies uploaded bytes; it does not establish source authenticity.</p></details>}</section>
      <aside className="panel evidence-facts"><div className="panel-heading"><div><h2>Linked facts</h2><p>Read the document beside the values it supports.</p></div></div><div className="linked-facts-body">{activeRecord ? <><div className="fact-record-heading"><strong>{activeRecord.number || activeRecord.reference || activeRecord.id}</strong><Badge tone="neutral">{activeRecord.number ? 'Invoice' : 'Payment'}</Badge></div>{[{label:activeRecord.number ? 'Invoice amount' : 'Payment amount',value:rupees(activeRecord.amount),field:'amount'},{label:activeRecord.number ? 'Invoice date' : 'Payment date',value:date(activeRecord.date),field:'date'},...(activeRecord.number ? [{label:'Delivery / acceptance',value:date(activeRecord.acceptance_date || activeRecord.delivery_date),field:activeRecord.acceptance_date ? 'acceptance_date' : 'delivery_date'},{label:'Agreed written terms',value:activeRecord.written_term_days == null ? 'No written term supplied' : `${activeRecord.written_term_days} days`,field:'written_term_days'}] : [{label:'Payment reference',value:activeRecord.reference || 'No reference supplied',field:'reference'}])].map(f => <div className="linked-fact" key={f.label}><label>{f.label}</label><div className="fact-value">{f.value}</div><div className="fact-provenance">{list(activeRecord.field_sources?.[f.field]).length ? <><CheckCheck size={14}/><span>Source linked</span></> : <><CircleAlert size={14}/><span>No field source supplied</span></>}</div>{list(activeRecord.field_sources?.[f.field]).map((id:any,idx) => <button className="fact-source" key={idx} onClick={() => openSource(id,activeRecord)}><FileText size={14}/><span>{sources.find(s => s.id === id)?.file || id}</span><ArrowUpRight size={12}/></button>)}</div>)}{activeRecord.due_date && <div className="calculated-fact"><span>Calculated due date</span><strong>{date(activeRecord.due_date)}</strong><p>{claim?.rules?.due_date || 'Verify the acceptance date and agreed written terms.'}</p></div>}</> : <div className="facts-empty"><FileText size={25}/><h3>No typed fact links yet</h3><p>This record is still available as evidence. Add supported typed records or review the extraction before use.</p></div>}{recordsForSource.length > 1 && <div className="other-records"><h3>Other linked records</h3>{recordsForSource.filter(r => r.id !== activeRecord?.id).map(r => <button className="text-button" key={r.id} onClick={() => openSource(activeSource,r)}>{r.number || r.reference || r.id} <ArrowRight size={12}/></button>)}</div>}{recordFields.length > 0 && <details className="all-field-links"><summary>All field references ({recordFields.length})</summary><SourceReferences source={{...activeSource,field_sources:activeRecord?.field_sources,related_refs:activeRecord?.source_refs}} sources={sources} onOpen={ref => openSource(ref,activeRecord)}/></details>}{activeRecord?.number && <InvoiceCorrection record={activeRecord} sources={sources} value={invoiceEdits[activeRecord.id] || {}} onChange={value => setInvoiceEdits(prev => ({...prev,[activeRecord.id]:value}))}/>} {activeSource && needsReview(activeSource.status) && <div className="evidence-review-controls"><h3>Review this source</h3><label>Review note for {activeSource.file}<textarea rows={3} value={sourceReviews[sourceId]?.reason || ''} placeholder="Record what you checked against the original document" onChange={e => setSourceReviews(prev => ({...prev,[sourceId]:{reason:e.target.value,replacement:prev[sourceId]?.replacement || ''}}))}/></label>{['ocr_unavailable','parse_error'].includes(activeSource.status) && <label>Readable replacement<select aria-label="Readable replacement" value={sourceReviews[sourceId]?.replacement || ''} onChange={e => setSourceReviews(prev => ({...prev,[sourceId]:{reason:prev[sourceId]?.reason || '',replacement:e.target.value}}))}><option value="">Choose replacement evidence</option>{sources.filter(s => s.id !== sourceId && ['parsed','reviewed'].includes(s.status)).map(s => <option key={s.id} value={s.id}>{s.file}</option>)}</select></label>}<p>Record your reviewer name below, then save the review decisions.</p></div>}<button className="button secondary full-width" onClick={() => goTo(view === 'review' ? 'overview' : 'review')}>{view === 'review' ? 'Back to invoice ledger' : 'Review claim packet'}<ArrowRight size={15}/></button></div></aside>
    </section>;
  }

  function reviewDecisions() {
    return <div className="review-decisions-layout"><section className="panel review-decisions"><div className="panel-heading"><div><h2>Review decisions <span className="count-pill">{blockers.length} open</span></h2><p>Resolve uncertain records and confirm assumptions before approval.</p></div><ShieldCheck size={20}/></div><div className="decision-content">{blockers.length ? blockers.map((b,idx) => <div className="blocker" key={b.id || idx}><div className="blocker-heading"><CircleAlert size={18}/><div><h3>{b.question || b.message}</h3>{b.question && b.question !== b.message && <p>{b.message}</p>}<span className="small muted">{String(b.code || 'review').replaceAll('_',' ')}</span></div>{b.source_id && <button className="text-button" onClick={() => openSource(b.source_id)}>Inspect source <ArrowUpRight size={13}/></button>}</div>{b.payment_id && <div className="resolution-fields"><label>Allocate receipt to an invoice<select aria-label="Allocate receipt to an invoice" value={resolutions[b.payment_id]?.invoice || ''} onChange={e => setResolutions(prev => ({...prev,[b.payment_id]:{invoice:e.target.value,reason:prev[b.payment_id]?.reason || '',source:prev[b.payment_id]?.source || ''}}))}><option value="">Choose the supported invoice</option>{invoices.filter(i => !b.candidates?.length || b.candidates.includes(i.id)).map(i => <option value={i.id} key={i.id}>{i.number || i.id} · {rupees(i.amount)}</option>)}</select></label><label>Supporting evidence<select aria-label="Supporting evidence" value={resolutions[b.payment_id]?.source || ''} onChange={e => setResolutions(prev => ({...prev,[b.payment_id]:{invoice:prev[b.payment_id]?.invoice || '',reason:prev[b.payment_id]?.reason || '',source:e.target.value}}))}><option value="">Choose a readable source</option>{sources.filter(s => !['ocr_unavailable','parse_error','superseded'].includes(s.status)).map(s => <option value={s.id} key={s.id}>{s.file}</option>)}</select></label><label className="span-two">Why is this the right allocation?<input value={resolutions[b.payment_id]?.reason || ''} placeholder="Reference the remittance note or other supporting record" onChange={e => setResolutions(prev => ({...prev,[b.payment_id]:{invoice:prev[b.payment_id]?.invoice || '',source:prev[b.payment_id]?.source || '',reason:e.target.value}}))}/></label>{synthetic && sources.some(s => s.id === 'REMIT-003') && <button className="text-button span-two" onClick={() => openSource('REMIT-003',payments.find(p => p.id === b.payment_id))}>Read the synthetic buyer remittance note <ArrowUpRight size={13}/></button>}</div>}</div>) : <div className="checks-clear"><CircleCheck size={23}/><div><h3>{claim ? 'Verification checks are clear.' : 'Create a claim to begin review.'}</h3><p>{claim ? 'Your final review and approval are still required.' : 'Add records or explore the synthetic demo.'}</p></div></div>}<div className="review-form"><label className="field-label">Reviewer name<input value={reviewer} onChange={e => setReviewer(e.target.value)} placeholder="Name recorded in the audit log"/></label><label className="check-field"><input type="checkbox" checked={buyerConfirmed} onChange={e => setBuyerConfirmed(e.target.checked)}/><div><strong>I have confirmed the buyer’s details.</strong><span>{claim?.buyer?.name} · {claim?.buyer?.address || 'Review the buyer profile.'}</span></div></label><label className="check-field"><input type="checkbox" checked={rateConfirmed} onChange={e => setRateConfirmed(e.target.checked)}/><div><strong>I have reviewed the rate assumptions.</strong><span>{synthetic ? 'These synthetic rates produce a demo packet only.' : 'Verify dated bank rates and the calculation convention.'}</span></div></label><button className="button primary" disabled={!canSaveReview} onClick={saveReview}><CheckCheck size={16}/> Save review decisions</button></div>{list(claim?.warnings).length > 0 && <details className="review-assumptions" open><summary>Assumptions in this packet</summary>{list(claim?.warnings).map((w,idx) => <p key={idx}><CircleAlert size={14}/>{typeof w === 'string' ? w : w.message || w.detail}</p>)}</details>}</div></section><section className="panel packet-panel"><div className="panel-heading"><div><h2>Claim packet</h2><p>{claim?.buyer?.name || 'For one buyer claim'}</p></div><FileCheck2 size={23}/></div><div className="packet-body">{['ODR field sheet','Draft demand letter','Interest schedule · PDF & CSV','Indexed evidence bundle','Review decisions & audit log'].map(t => <div className="packet-item" key={t}><FileText size={16}/>{t}</div>)}<dl className="packet-calculation"><div><dt>Invoice total</dt><dd>{rupees(totals.invoiced)}</dd></div><div><dt>Allocated bank receipts</dt><dd>− {rupees(totals.allocated_bank)}</dd></div><div><dt>Evidenced TDS</dt><dd>− {rupees(totals.tds_recognized)}</dd></div><div><dt>Outstanding principal</dt><dd>{rupees(totals.principal)}</dd></div><div><dt>Calculated interest</dt><dd>+ {rupees(totals.interest)}</dd></div></dl><div className="packet-total"><span>Total claim</span><strong>{rupees(totals.total)}</strong></div>{Number(totals.unallocated) > 0 && <p className="packet-blocked"><CircleAlert size={15}/>{rupees(totals.unallocated)} awaiting allocation</p>}{claim?.status === 'approved' ? <><Badge tone="green"><BadgeCheck size={13}/> Human approval recorded</Badge><button className="button primary full-width" onClick={download} disabled={!!busy}><ArrowDownToLine size={17}/> Download claim packet</button></> : <><label className="check-field approval-field"><input type="checkbox" checked={approvalChecked} onChange={e => setApprovalChecked(e.target.checked)} disabled={!claim || blockers.length > 0}/><span>I have reviewed the records, calculations, and assumptions in this packet.</span></label><button className="button primary full-width" onClick={approve} disabled={!!busy || !claim || blockers.length > 0 || !approvalChecked || !reviewer.trim()}><ShieldCheck size={16}/> Approve packet</button><p className="export-lock">{blockers.length ? `Resolve ${blockers.length} open questions to enable approval.` : !reviewer.trim() ? 'Add your reviewer name to record approval.' : 'Confirm your review to approve this packet.'}</p></>}<p className="packet-disclaimer">A local download for self-filing. Nothing is sent to the buyer or filed automatically.</p></div></section></div>;
  }

  return <div className="app-shell">
    {menu && <button className="nav-scrim" aria-label="Close navigation" onClick={() => setMenu(false)}/>}
    <aside className={`sidebar ${menu ? 'sidebar-open' : ''}`}><a className="brand" href="#" onClick={e => {e.preventDefault();goTo('overview');}}><span className="brand-mark"><Layers3 size={24}/></span>bakaya<span className="brand-period">.</span></a><div className="workspace-card"><span className="workspace-avatar">{claim?.supplier?.name?.slice(0,2).toUpperCase() || 'BK'}</span><div><strong title={claim?.supplier?.name}>{claim?.supplier?.name || 'Your business'}</strong><span>{claim?.supplier?.category ? `${claim.supplier.category} enterprise` : 'Receivables workspace'}</span></div></div><nav aria-label="Main navigation">{nav.filter(n => ['overview','documents','review'].includes(n.id)).map(({id,label,icon:Icon}) => <button key={id} className={`nav-item ${view === id ? 'active' : ''}`} aria-current={view === id ? 'page' : undefined} onClick={() => goTo(id)}><Icon size={18}/>{label}{id === 'review' && blockers.length > 0 && <span className="nav-count">{blockers.length}</span>}</button>)}<details className="nav-details" open={['ledger','interest','audit'].includes(view) || undefined}><summary>More details <ChevronDown size={15}/></summary>{nav.filter(n => ['ledger','interest','audit'].includes(n.id)).map(({id,label,icon:Icon}) => <button key={id} className={`nav-item ${view === id ? 'active' : ''}`} aria-current={view === id ? 'page' : undefined} onClick={() => goTo(id)}><Icon size={18}/>{label}{id === 'review' && blockers.length > 0 && <span className="nav-count">{blockers.length}</span>}</button>)}</details></nav><div className="sidebar-bottom"><div className="security-note"><ShieldCheck size={20}/><div><strong>You stay in control</strong><p>Review every claim.<br/>Nothing is sent automatically.</p></div></div><button className="sidebar-help" onClick={() => setHelp(true)}><HelpCircle size={17}/> How Bakaya works <ArrowUpRight size={14}/></button><div className="user-profile"><span className="user-avatar">YO</span><div><strong>Your workspace</strong><span>Local · single-buyer claims</span></div></div></div></aside>
    <main className="main"><header className="topbar"><div className="breadcrumbs"><button className="mobile-menu icon-button" aria-label="Open navigation" onClick={() => setMenu(!menu)}><Menu size={21}/></button><span>Workspace</span><ChevronRight size={14}/><span>{claim?.buyer?.name || 'Claims'}</span><ChevronRight size={14}/><strong>{currentLabel}</strong></div><div className="topbar-right"><span className="private-label"><ShieldCheck size={14}/> Local workspace</span><button className="help-button" aria-label="Help" onClick={() => setHelp(true)}><HelpCircle size={19}/></button><span className="top-avatar">YO</span></div></header>
      <div className="page-content">
        {error && <div role="alert" className="alert alert-error"><CircleAlert size={18}/><span>{error} Review the records and try the action again.</span><button aria-label="Dismiss error" onClick={() => setError('')}><X size={16}/></button></div>}{notice && <div role="status" className="alert alert-success"><CircleCheck size={18}/><span>{notice}</span><button aria-label="Dismiss notification" onClick={() => setNotice('')}><X size={16}/></button></div>}
        <div className="page-heading"><div><h1>{view === 'overview' ? `${claim?.buyer?.name || 'Your receivables'} / Claim preparation` : view === 'review' ? 'Evidence review / Claim approval' : currentLabel}</h1><p>{view === 'overview' ? 'Bring your records together. Review the evidence and confirm what belongs in this claim.' : view === 'review' || view === 'documents' ? 'Read the source documents beside their linked facts. Resolve uncertainty before approving.' : view === 'ledger' ? 'Follow invoices and bank receipts, with each allocation supported by evidence.' : view === 'interest' ? 'Inspect each calculation period and the source for its bank rate.' : 'A transparent record of claim preparation and human decisions.'}</p></div><div className="heading-actions">{synthetic && <Badge tone="blue">Synthetic demo</Badge>}<button className="button secondary" onClick={() => setModal(true)} disabled={!!busy}><Plus size={17}/> New claim</button></div></div>
        <div className="claim-toolbar"><div><BookOpen size={17}/><strong>{claim?.buyer?.name || 'No active claim'}</strong>{claim && <Badge tone={claim.status === 'approved' || claim.status === 'ready' ? 'green' : 'amber'}>{statusLabel[claim.status] || claim.status}</Badge>}</div><div className="claim-toolbar-actions">{cases.length > 1 && <select aria-label="Select claim" value={claim?.id || ''} onChange={e => selectCase(e.target.value)} disabled={!!busy}>{cases.map(c => <option key={c.id} value={c.id}>{c.buyer?.name || c.name || c.id}</option>)}</select>}{claim && <button className="text-button" onClick={() => perform('Rechecking records',() => api(`/cases/${claim.id}/run`,json({mode:'fixed'})),'Claim recalculated from the current records.')} disabled={!!busy}><RefreshCw size={14}/> Recheck</button>}</div></div>
        {busy && <div className="working-bar" role="status"><LoaderCircle size={16} className="spin"/>{busy}…</div>}
        {claim && <section className="preparation-strip" aria-label="Claim preparation state"><div className="preparation-steps"><span><CircleCheck size={18}/><strong>Records</strong><small>{sources.length} sources</small></span><ChevronRight size={14}/><span><FileText size={18}/><strong>Invoices</strong><small>{invoices.length} records</small></span><ChevronRight size={14}/><span><ShieldCheck size={18}/><strong>Review</strong><small>{blockers.length ? `${blockers.length} open questions` : 'Checks clear'}</small></span><ChevronRight size={14}/><span className={claim.status === 'approved' ? 'complete-step' : 'pending-step'}>{claim.status === 'approved' ? <CircleCheck size={18}/> : <Clock3 size={18}/>}<strong>Approval</strong><small>{claim.status === 'approved' ? 'Recorded' : 'Your confirmation'}</small></span></div><div className="preparation-action"><button className="button secondary" disabled={!!busy} onClick={() => runPreparation(!!preparationAgent)}><RefreshCw size={14}/>{preparationAgent ? 'Resume preparation' : 'Prepare claim'}</button></div><details className="agent-details"><summary>Agent details <ChevronDown size={15}/></summary><div className="agent-settings"><label className="model-toggle"><input type="checkbox" checked={modelPlanning} onChange={e => setModelPlanning(e.target.checked)} disabled={!!busy}/><span>Use model planning<small>Optional · shared $15 budget</small></span></label>{preparationAgent && <p>Preparation status: <strong>{String(preparationAgent.status || 'Prepared').replaceAll('_',' ')}</strong></p>}<p>Code calculates amounts; model planning is optional and cannot approve a packet.</p></div></details></section>}

        {view === 'overview' && (!claim ? <section className="start-workspace"><div><h2>Start with the records.<br/><em>Make a claim you can follow.</em></h2><p>Create a supplier and buyer profile, add invoices and payment records, then review every assumption before a local packet download.</p><div className="start-actions"><button className="button primary" onClick={() => setModal(true)}><Plus size={17}/> Create your first claim</button><button className="button secondary" onClick={loadDemo} disabled={!!busy}><Sparkles size={16}/> Explore a demo</button></div><p className="start-note"><ShieldCheck size={15}/> The demo contains fictional records and synthetic rates.</p></div><div className="start-requirements"><h3>Bring the paper trail</h3><ul><li>Invoices and agreed payment terms</li><li>Delivery or acceptance evidence</li><li>Bank receipts and remittance notes</li><li>Supplier registration and buyer details</li></ul><span>Uncertain records stay open for your review.</span></div></section> : <><div className="ledger-workspace"><div>{invoiceLedger()}<details className="workspace-details"><summary>Recent decisions <ChevronDown size={16}/></summary>{activityTable(true)}</details></div>{selectedRecordPanel()}</div>{evaluated?.baseline && evaluated?.fixed && <details className="panel evaluation-panel"><summary><span>Measured synthetic evaluation</span><Badge tone="blue">20 labeled scenarios</Badge><ChevronDown size={16}/></summary><div className="evaluation-body"><p>Local results from fictional fixtures; these are not real customer outcomes.</p><div className="table-wrap"><table><thead><tr><th>Check</th><th className="numeric">Amount-only baseline</th><th className="numeric">Evidence-aware matcher</th></tr></thead><tbody>{[{label:'Payment-match accuracy',key:'matching_accuracy',render:(v:any) => `${v}%`},{label:'Maximum interest error',key:'max_interest_error',render:rupees},{label:'False short-payments',key:'false_short_payments',render:String},{label:'Planted ambiguities flagged',key:'ambiguities_flagged',render:String}].map(m => <tr key={m.key}><td>{m.label}</td><td className="numeric">{m.render(evaluated.baseline[m.key])}</td><td className="numeric">{m.render(evaluated.fixed[m.key])}</td></tr>)}</tbody></table></div><div className="evaluation-actions"><button className="button secondary" disabled={!!busy} onClick={() => perform('Running baseline',() => api(`/cases/${claim.id}/run`,json({mode:'baseline'})),'Deliberately flawed baseline recorded. This version cannot be approved.')}>Run baseline</button><button className="button secondary" disabled={!!busy} onClick={() => runPreparation(false,true)}>Simulate tool failure</button></div></div></details>}</>)}
        {view === 'documents' && evidenceWorkspace()}
        {view === 'review' && <>{evidenceWorkspace()}{reviewDecisions()}</>}
        {view === 'ledger' && <>{invoiceLedger()}<section className="panel payment-panel"><div className="panel-heading"><div><h2>Payments & allocations <span className="count-pill">{payments.length}</span></h2><p>Bank statement total: {rupees(totals.bank_received)} · Allocated: {rupees(totals.allocated_bank)}</p></div></div>{payments.length ? <div className="table-wrap"><table><thead><tr><th>Payment / reference</th><th>Date</th><th className="numeric">Bank receipt</th><th>Allocation</th><th>Evidence</th></tr></thead><tbody>{payments.map(p => <tr key={p.id}><td><strong>{p.reference || p.id}</strong><span className="table-sub">{p.id}</span></td><td>{date(p.date)}</td><td className="numeric money">{rupees(p.amount)}</td><td>{list(claim?.matches).filter(m => m.payment_id === p.id).length ? list(claim?.matches).filter(m => m.payment_id === p.id).map((m,idx) => <div className="allocation" key={idx}><strong>{m.invoice_id}</strong><span>{rupees(m.amount)}{Number(m.tds_amount) > 0 ? ` + ${rupees(m.tds_amount)} TDS` : ''}</span><small>{m.reason}</small></div>) : <button className="text-button amber-text" onClick={() => goTo('review')}>Review allocation <ArrowRight size={13}/></button>}</td><td>{refs(p)}</td></tr>)}</tbody></table></div> : <Empty title="No bank receipts yet" icon={Banknote}>Add a supported bank statement to reconcile payments.</Empty>}</section></>}
        {view === 'interest' && <><div className="convention-note"><ShieldCheck size={18}/><div><h2>Calculation convention</h2><p>{claim?.convention || 'Actual/365 with monthly anniversary rests. Review the convention before using a claim.'}</p>{claim?.rules?.due_date && <p>{claim.rules.due_date}</p>}</div></div><section className="panel"><div className="panel-heading"><div><h2>Monthly interest schedule</h2><p>{list(claim?.schedule).length} periods · through {date(claim?.as_of)} · ends shown as exclusive dates</p></div><Badge tone={rateConfirmed ? 'green' : 'amber'}>{rateConfirmed ? 'Rate assumptions reviewed' : 'Rate review required'}</Badge></div>{list(claim?.schedule).length ? <div className="table-wrap"><table><thead><tr><th>Invoice</th><th>Period</th><th className="numeric">Days</th><th className="numeric">Principal</th><th className="numeric">Capitalised interest</th><th className="numeric">Bank rate</th><th className="numeric">3× rate</th><th className="numeric">Interest</th><th>Rate evidence</th></tr></thead><tbody>{list(claim?.schedule).map((s,idx) => <tr key={idx}><td><strong>{s.invoice_id}</strong></td><td className="nowrap">{date(s.start)}<span className="table-sub">to {date(s.end)}</span></td><td className="numeric">{s.days}</td><td className="numeric money">{rupees(s.principal)}</td><td className="numeric money">{rupees(s.capitalized_interest)}</td><td className="numeric">{Number(s.bank_rate)}%</td><td className="numeric">{Number(s.annual_rate)}%</td><td className="numeric money">{rupees(s.interest)}</td><td><button className="source-link" onClick={() => openSource(s.rate_source_refs?.[0] || {file:'Rate source',text:s.rate_source},s)}>View source <ArrowUpRight size={12}/></button></td></tr>)}</tbody></table></div> : <Empty title="No calculation periods yet" icon={Clock3}>Acceptance evidence and dated rates are needed to calculate interest.</Empty>}<div className="schedule-total"><span>Total calculated interest</span><strong>{rupees(totals.interest)}</strong></div></section></>}
        {view === 'audit' && activityTable()}
        {preparationAgent && <details className="panel agent-log"><summary><History size={16}/><strong>Preparation checkpoints</strong><span>{String(preparationAgent.status || 'Recorded').replaceAll('_',' ')}</span><ChevronDown size={16}/></summary><div className="agent-log-body">{list(preparationAgent.steps).length ? <ol>{list(preparationAgent.steps).map((step,idx) => <li key={idx}><strong>{String(step.tool || step.action || 'Step').replaceAll('_',' ')}</strong><Badge tone={['failed','error'].includes(step.status) ? 'amber' : 'neutral'}>{step.status || 'Recorded'}</Badge><p>{step.summary || step.detail}</p><small>{step.at ? new Date(step.at).toLocaleString('en-IN') : ''}</small></li>)}</ol> : <p>No completed tool steps were returned.</p>}{preparationAgent.next_tool && <p>Next tool: <strong>{String(preparationAgent.next_tool).replaceAll('_',' ')}</strong></p>}<p>These are persisted tool outcomes. Only recorded extraction calls are attributed to a model.</p></div></details>}
        <footer className="page-footer"><span className="footer-brand">bakaya.</span><span>Document preparation for self-filing · review all assumptions before use.</span><span>{synthetic ? 'Synthetic records' : 'Local workspace'}</span></footer>
      </div>
    </main>
    <input hidden type="file" ref={fileRef} multiple accept=".pdf,.png,.jpg,.jpeg,.csv,.xlsx,.txt,.webp,.tif,.tiff" onChange={e => uploadFiles(e.target.files)}/>
    {modal && <NewClaimModal busy={!!busy} onClose={() => setModal(false)} onCreate={async(profile,files) => {const result = await perform('Creating your claim',async() => {const created = await api('/cases',json(profile));setClaim(created);localStorage.setItem('bakaya.case',created.id);if(files.length){const form = new FormData();files.forEach(f => form.append('files',f));await api(`/cases/${created.id}/upload`,{method:'POST',body:form});return api(`/cases/${created.id}/run`,json({mode:'fixed'}));}return created;},'Claim created. Add and review its supporting records.');if(result){setCases(prev => [result,...prev]);setModal(false);goTo('documents');}}}/>}
    {help && <Dialog.Root open={help} onOpenChange={setHelp}><Dialog.Portal><Dialog.Overlay className="dialog-overlay"/><Dialog.Content className="modal help-modal dialog-content"><button className="modal-close icon-button" aria-label="Close help" onClick={() => setHelp(false)}><X size={20}/></button><Dialog.Title asChild><h2>Follow the paper trail.</h2></Dialog.Title><Dialog.Description asChild><p>Bakaya assembles records into a reviewable delayed-payment claim. Code calculates the money; you confirm the evidence and approve the packet.</p></Dialog.Description><div className="help-steps"><p><strong>Add records.</strong> Create a supplier and buyer profile, then upload evidence.</p><p><strong>Inspect the ledger.</strong> Review dates, allocations, interest, and linked source documents.</p><p><strong>Approve a local packet.</strong> Unresolved checks prevent export. Nothing is filed or sent automatically.</p></div><p className="muted">The demo uses fictional records and synthetic rates. Real claims require verified facts and professional review of legal assumptions.</p><section className="build-evidence"><h3>Hackathon evidence checklist</h3><p><strong>Agent quality · 30%.</strong> Persisted preparation steps, checkpoints, model opt-in, and review gates are implemented. Inspect recorded outcomes in this workspace.</p><p><strong>Sponsor use · 25%.</strong> Neatlogs diagnostic authentication succeeded; application trace readback remains a separate check. Entire is enabled, with hook approval and a captured checkpoint pending. cfo.ai workflow evidence is pending.</p><p><strong>Demo · 20%.</strong> Synthetic records and local exports are available. The final recorded demonstration remains pending.</p><p><strong>Building in public · 15%.</strong> Development commits are recorded. Public posts and publicly accessible submission evidence remain pending.</p><p><strong>Usefulness and originality · 10%.</strong> Evidence-backed receivables preparation is demonstrated with synthetic records. CA review and real customer validation have not occurred.</p></section><button className="button primary" onClick={() => {setHelp(false);loadDemo();}} disabled={!!busy}><Sparkles size={16}/> Explore a synthetic case</button></Dialog.Content></Dialog.Portal></Dialog.Root>}
  </div>;
}

function InvoiceCorrection({record,sources,value,onChange}:{record:Item;sources:Item[];value:Item;onChange:(value:Item)=>void}) {
  const fields = value.fields || {};
  function setField(key:string,raw:string) {
    const next={...fields};
    if (!raw) delete next[key]; else next[key]=key === 'written_term_days' ? Number(raw) : raw;
    onChange({...value,fields:next});
  }
  return <details className="invoice-correction"><summary>Correct invoice facts</summary><p>Enter only the corrections supported by readable evidence. Saving changes rechecks the claim and invalidates any earlier approval.</p><label>Correction evidence<select value={value.source_id || ''} onChange={e => onChange({...value,source_id:e.target.value})}><option value="">Choose supporting document</option>{sources.filter(s => ['parsed','reviewed'].includes(s.status)).map(s => <option key={s.id} value={s.id}>{s.file}</option>)}</select></label><label>Correct invoice amount<input type="number" min="0.01" step="0.01" value={fields.amount || ''} placeholder={String(record.amount)} onChange={e => setField('amount',e.target.value)}/></label><label>Correct invoice date<input type="date" value={fields.date || ''} onChange={e => setField('date',e.target.value)}/></label><label>Correct acceptance date<input type="date" value={fields.acceptance_date || ''} onChange={e => setField('acceptance_date',e.target.value)}/></label><label>Correct written term (days)<input type="number" min="0" max="3650" value={fields.written_term_days ?? ''} placeholder={record.written_term_days == null ? 'No written term supplied' : String(record.written_term_days)} onChange={e => setField('written_term_days',e.target.value)}/></label><label>Reason for correcting this invoice<textarea rows={3} value={value.reason || ''} placeholder="Record the facts you checked in the supporting document" onChange={e => onChange({...value,reason:e.target.value})}/></label><p>Record your reviewer name below, then use Save review decisions.</p>{Object.keys(fields).length > 0 && <button className="text-button" onClick={() => onChange({})}>Discard corrections <X size={12}/></button>}</details>;
}

function SourceReferences({ source, sources, caseId, onOpen }: { source: Item; sources: Item[]; caseId?: string; onOpen: (ref: any) => void }) {
  const related = list(source.related_refs);
  const fields = Object.entries(source.field_sources || {}) as [string, string[]][];
  return <><div className="source-reference-list">{related.length > 1 && <><h4>All linked records</h4>{related.map((ref: any, idx) => { const id = typeof ref === 'string' ? ref : ref.source_id || ref.id; return <button key={idx} className="source-link" onClick={() => onOpen(ref)}><FileText size={13} /> {sources.find(s => s.id === id)?.file || id} <ArrowUpRight size={11} /></button>; })}</>}{fields.length > 0 && <><h4>Evidence by field</h4>{fields.map(([field, ids]) => <div className="field-source-row" key={field}><span>{field.replaceAll('_', ' ')}</span><div>{ids.map(id => <button key={id} className="source-link" onClick={() => onOpen(id)}>{sources.find(s => s.id === id)?.file || id} <ArrowUpRight size={10} /></button>)}</div></div>)}</>}</div>{source.stored_name && caseId && <a className="button secondary full-width source-download" href={`/api/cases/${caseId}/sources/${source.id}/download`} download><ArrowDownToLine size={15} /> Download original file</a>}</>;
}

function NewClaimModal({ onClose, onCreate, busy }: { onClose: () => void; onCreate: (profile: Item, files: File[]) => Promise<void>; busy: boolean }) {
  const [files, setFiles] = useState<File[]>([]);
  const [form, setForm] = useState({ name: '', category: 'micro', activity: 'manufacturing', udyam_number: '', udyam_date: '', address: '', buyer_name: '', buyer_address: '', as_of: new Date().toLocaleDateString('en-CA') });
  const upload = useRef<HTMLInputElement>(null);
  const update = (key: string, value: string) => setForm(prev => ({ ...prev, [key]: value }));
  function submit(e: FormEvent) {
    e.preventDefault();
    onCreate({ supplier: { name: form.name, category: form.category, activity: form.activity, udyam_number: form.udyam_number, udyam_date: form.udyam_date, address: form.address }, buyer: { name: form.buyer_name, address: form.buyer_address }, as_of: form.as_of, invoices: [], payments: [], rates: [] }, files);
  }
  return <Dialog.Root open onOpenChange={open => {if (!open && !busy) onClose();}}><Dialog.Portal><Dialog.Overlay className="dialog-overlay"/><Dialog.Content className="modal create-modal dialog-content" onEscapeKeyDown={e => {if (busy) e.preventDefault();}} onPointerDownOutside={e => {if (busy) e.preventDefault();}}><div className="modal-heading"><div><Dialog.Title asChild><h2>Create a buyer claim</h2></Dialog.Title><Dialog.Description asChild><p>One supplier, one buyer, and the records between them.</p></Dialog.Description></div><button className="icon-button" aria-label="Close create claim" disabled={busy} onClick={onClose}><X size={22} /></button></div><form onSubmit={submit}><div className="form-section-title">Your business</div><div className="form-grid"><label className="span-two">Legal business name<input required value={form.name} onChange={e => update('name', e.target.value)} placeholder="Name on your Udyam registration" /></label><label>Enterprise category<select value={form.category} onChange={e => update('category', e.target.value)}><option value="micro">Micro enterprise</option><option value="small">Small enterprise</option></select></label><label>Business activity<select value={form.activity} onChange={e => update('activity', e.target.value)}><option value="manufacturing">Manufacturing</option><option value="services">Services</option></select></label><label>Udyam registration number<input required value={form.udyam_number} onChange={e => update('udyam_number', e.target.value)} placeholder="UDYAM-XX-00-0000000" /></label><label>Udyam registration date<input required type="date" value={form.udyam_date} onChange={e => update('udyam_date', e.target.value)} /></label><label className="span-two">Business address<textarea required rows={2} value={form.address} onChange={e => update('address', e.target.value)} placeholder="Registered address, including state and PIN" /></label></div><div className="form-section-title">Your buyer</div><div className="form-grid"><label className="span-two">Buyer’s legal name<input required value={form.buyer_name} onChange={e => update('buyer_name', e.target.value)} placeholder="Name on the invoice / purchase order" /></label><label className="span-two">Buyer’s address<textarea required rows={2} value={form.buyer_address} onChange={e => update('buyer_address', e.target.value)} placeholder="Registered or correspondence address" /></label><label>Calculate interest through<input required type="date" value={form.as_of} onChange={e => update('as_of', e.target.value)} /></label></div><div className="form-section-title">Supporting records <span className="optional-label">Optional now</span></div><button type="button" className="modal-dropzone" onClick={() => upload.current?.click()}><UploadCloud size={25} /><strong>{files.length ? `${files.length} file${files.length > 1 ? 's' : ''} selected` : 'Add your supporting documents'}</strong><span>PDF, images, CSV, XLSX, or chat export</span></button><input hidden ref={upload} type="file" multiple accept=".pdf,.png,.jpg,.jpeg,.csv,.xlsx,.txt,.webp,.tif,.tiff" onChange={e => setFiles(Array.from(e.target.files || []))} />{files.length > 0 && <div className="selected-files">{files.map((f, idx) => <span key={idx}><FileText size={13} />{f.name}<button type="button" aria-label={`Remove ${f.name}`} onClick={() => setFiles(prev => prev.filter((_, i) => idx !== i))}><X size={12} /></button></span>)}</div>}<div className="modal-footer"><span><ShieldCheck size={14} /> No automatic filing or sending</span><button className="button primary" type="submit" disabled={busy}>{busy ? <LoaderCircle className="spin" size={16} /> : <Plus size={16} />} Create claim</button></div></form></Dialog.Content></Dialog.Portal></Dialog.Root>;
}

